import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface FishPhysicsConfig {
  minSpeed: number;
  maxSpeed: number;
  diveInterval: number;
  verticalFreedom: number;
  turnSpeed: number;
}

export interface SwimShaderConfig {
  bodySpeed?: number;
  bodyFreq?: number;
  bodyAmp?: number;
  finSpeed?: number;
  pectoralAmp?: number;
  caudalWhip?: number;
}

export interface FishConfig {
  id: string;
  name: string;
  modelPath: string;
  behavior?: 'normal' | 'bottom_dweller';
  transform: {
    scale?: number;
    rotX?: number;
    rotY?: number;
    rotZ?: number;
  };
  physics: FishPhysicsConfig;
  swimShader: SwimShaderConfig;
}

export interface CustomShader {
  uniforms: { [key: string]: { value: any } };
  vertexShader: string;
  fragmentShader: string;
}

interface FishInstance {
  group: THREE.Group;
  velocity: THREE.Vector3;
  targetVelocity: THREE.Vector3;
  speed: number;
  config: FishConfig;
  preferredDepth: number;
  timer: number;
}

interface LoadedTemplate {
  wrapper: THREE.Group;
  config: FishConfig;
}

export class FishManager {
  private scene: THREE.Scene;
  private bounds: THREE.Vector3;
  private targetCount: number;
  private configs: FishConfig[];
  private templates: LoadedTemplate[] = [];
  private fishList: FishInstance[] = [];
  private activeShaders: CustomShader[] = [];
  private loader!: GLTFLoader;

  constructor(scene: THREE.Scene, tankBounds: THREE.Vector3, count = 20, configs: FishConfig[] = []) {
    this.scene = scene;
    this.bounds = tankBounds;
    this.targetCount = count;
    this.configs = configs;

    this.initLoader();
    this.loadModels();
  }

  private initLoader() {
    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');

    this.loader = new GLTFLoader();
    this.loader.setDRACOLoader(dracoLoader);
  }

  private loadModels() {
    const promises = this.configs.map((cfg) => {
      return new Promise<LoadedTemplate | null>((resolve) => {
        this.loader.load(
          cfg.modelPath,
          (gltf) => {
            const model = gltf.scene;

            const box = new THREE.Box3().setFromObject(model);
            const size = box.getSize(new THREE.Vector3());
            const maxDim = Math.max(size.x, size.y, size.z);
            const scaleFactor = (1.0 / (maxDim || 1.0)) * (cfg.transform.scale || 1.0);

            const wrapper = new THREE.Group();
            model.scale.setScalar(scaleFactor);

            const rotX = cfg.transform.rotX ?? 0;
            const rotY = cfg.transform.rotY ?? 0;
            const rotZ = cfg.transform.rotZ ?? 0;
            model.rotation.set(rotX, rotY, rotZ);

            wrapper.add(model);

            resolve({ wrapper, config: cfg });
          },
          undefined,
          (err) => {
            console.error(`[FishEngine] Model yüklenemedi: ${cfg.modelPath}`, err);
            resolve(null);
          }
        );
      });
    });

    Promise.all(promises).then((results) => {
      this.templates = results.filter((r): r is LoadedTemplate => r !== null);
      if (this.templates.length > 0) {
        this.setFishCount(this.targetCount);
      }
    });
  }

  private bindShader(rootMesh: THREE.Object3D, shaderCfg: SwimShaderConfig) {
    rootMesh.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh;
        if (mesh.material) {
          const mat = (mesh.material as THREE.Material).clone() as THREE.MeshStandardMaterial;

          const hasColor = Boolean(mesh.geometry.attributes.color);
          mat.vertexColors = hasColor;

          if (hasColor) {
            mat.defines = mat.defines || {};
            mat.defines.USE_COLOR = '';
          }

          mat.onBeforeCompile = (shader:CustomShader) => {
            shader.uniforms.uTime = { value: 0 };
            shader.uniforms.uPhase = { value: Math.random() * 10.0 };

            shader.uniforms.uBodySpeed = { value: shaderCfg.bodySpeed ?? 2.0 };
            shader.uniforms.uBodyFreq = { value: shaderCfg.bodyFreq ?? 3.0 };
            shader.uniforms.uBodyAmp = { value: shaderCfg.bodyAmp ?? 0.02 };
            shader.uniforms.uFinSpeed = { value: shaderCfg.finSpeed ?? 6.0 };
            shader.uniforms.uPectoralAmp = { value: shaderCfg.pectoralAmp ?? 0.04 };
            shader.uniforms.uCaudalWhip = { value: shaderCfg.caudalWhip ?? 0.05 };

            shader.vertexShader = `
              uniform float uTime;
              uniform float uPhase;
              uniform float uBodySpeed;
              uniform float uBodyFreq;
              uniform float uBodyAmp;
              uniform float uFinSpeed;
              uniform float uPectoralAmp;
              uniform float uCaudalWhip;
              ${shader.vertexShader}
            `;

            shader.vertexShader = shader.vertexShader.replace(
              '#include <begin_vertex>',
              `
              #include <begin_vertex>

              // 1. GÖVDE OMURGA SALINIMI
              float spineT = smoothstep(0.05, 0.45, abs(position.z));
              float bodySwing = sin(uTime * uBodySpeed + uPhase + position.z * uBodyFreq) * uBodyAmp * spineT;
              transformed.x += bodySwing;

              // 2. YÜZGEÇLER VE KUYRUK (MİKRO HAREKETLER)
              #ifdef USE_COLOR
                float pectoralMask = smoothstep(0.1, 0.9, color.r); 
                float caudalMask   = smoothstep(0.1, 0.9, color.g); 

                // GÖĞÜS YÜZGEÇLERİ (Kırmızı Kanal)
                if (pectoralMask > 0.01) {
                  float sideSign = sign(position.x);
                  float stroke = sin(uTime * uFinSpeed + uPhase) * uPectoralAmp * pectoralMask;
                  transformed.x += stroke * 0.7 * sideSign;
                  transformed.z += cos(uTime * uFinSpeed + uPhase) * (uPectoralAmp * 0.4) * pectoralMask;
                }

                // KUYRUK TÜLÜ (Yeşil Kanal)
                if (caudalMask > 0.01) {
                  float tailWhip = sin(uTime * uBodySpeed + uPhase + position.z * (uBodyFreq * 1.1)) * uCaudalWhip * caudalMask;
                  transformed.x += tailWhip;
                }
              #endif
              `
            );

            this.activeShaders.push(shader);
          };

          mesh.material = mat;
        }
      }
    });
  }

  public addFish() {
    if (this.templates.length === 0) return;

    const templateObj = this.templates[Math.floor(Math.random() * this.templates.length)];
    const { wrapper, config } = templateObj;

    const margin = 1.0;
    const maxX = this.bounds.x / 2 - margin;
    const maxY = this.bounds.y / 2 - margin;
    const maxZ = this.bounds.z / 2 - margin;
    const bottomY = -this.bounds.y / 2 + 0.35;

    const fishGroup = new THREE.Group();
    const fishClone = SkeletonUtils.clone(wrapper);

    this.bindShader(fishClone, config.swimShader);
    fishGroup.add(fishClone);

    const isBottomDweller = config.behavior === 'bottom_dweller';
    const initialY = isBottomDweller ? bottomY : THREE.MathUtils.randFloat(-maxY * 0.5, maxY * 0.5);

    fishGroup.position.set(
      THREE.MathUtils.randFloat(-maxX + 0.5, maxX - 0.5),
      initialY,
      THREE.MathUtils.randFloat(-maxZ + 0.5, maxZ - 0.5)
    );

    const speed = THREE.MathUtils.randFloat(config.physics.minSpeed, config.physics.maxSpeed);
    const velocity = new THREE.Vector3(
      THREE.MathUtils.randFloatSpread(1),
      isBottomDweller ? 0 : THREE.MathUtils.randFloatSpread(0.04),
      THREE.MathUtils.randFloatSpread(1)
    ).normalize().multiplyScalar(speed);

    this.scene.add(fishGroup);

    this.fishList.push({
      group: fishGroup,
      velocity: velocity,
      targetVelocity: velocity.clone(),
      speed: speed,
      config: config,
      preferredDepth: initialY,
      timer: Math.random() * config.physics.diveInterval
    });
  }

  public removeFish() {
    if (this.fishList.length === 0) return;
    const fish = this.fishList.pop();
    if (fish) {
      this.scene.remove(fish.group);
    }
  }

  public setFishCount(newCount: number) {
    this.targetCount = newCount;
    if (this.templates.length === 0) return;

    while (this.fishList.length < newCount) this.addFish();
    while (this.fishList.length > newCount) this.removeFish();
  }

  public update(elapsedTime: number) {
    for (let i = 0; i < this.activeShaders.length; i++) {
      this.activeShaders[i].uniforms.uTime.value = elapsedTime;
    }

    const margin = 0.8;
    const minX = -this.bounds.x / 2 + margin;
    const maxX = this.bounds.x / 2 - margin;
    const minY = -this.bounds.y / 2 + margin;
    const maxY = this.bounds.y / 2 - margin;
    const minZ = -this.bounds.z / 2 + margin;
    const maxZ = this.bounds.z / 2 - margin;
    const bottomY = -this.bounds.y / 2 + 0.35;

    for (let i = 0; i < this.fishList.length; i++) {
      const fish = this.fishList[i];
      const pos = fish.group.position;
      const phys = fish.config.physics;
      const isBottomDweller = fish.config.behavior === 'bottom_dweller';

      if (isBottomDweller) {
        fish.preferredDepth = bottomY;
        fish.targetVelocity.y = (bottomY - pos.y) * 0.1;
      } else {
        fish.timer++;
        if (fish.timer > phys.diveInterval) {
          fish.preferredDepth = THREE.MathUtils.randFloat(minY + 0.4, maxY - 0.4);
          fish.timer = 0;
        }
        const depthDiff = fish.preferredDepth - pos.y;
        fish.targetVelocity.y = depthDiff * phys.verticalFreedom;
      }

      if (Math.random() < 0.01) {
        fish.targetVelocity.x += THREE.MathUtils.randFloatSpread(0.02);
        fish.targetVelocity.z += THREE.MathUtils.randFloatSpread(0.02);
      }

      const buffer = 1.3;
      const steer = 0.0025;
      if (pos.x > maxX - buffer) fish.targetVelocity.x -= steer;
      if (pos.x < minX + buffer) fish.targetVelocity.x += steer;

      if (!isBottomDweller) {
        if (pos.y > maxY - buffer) fish.targetVelocity.y -= steer;
        if (pos.y < minY + buffer) fish.targetVelocity.y += steer;
      }

      if (pos.z > maxZ - buffer) fish.targetVelocity.z -= steer;
      if (pos.z < minZ + buffer) fish.targetVelocity.z += steer;

      if (!isBottomDweller) {
        fish.targetVelocity.y = THREE.MathUtils.clamp(fish.targetVelocity.y, -0.008, 0.008);
      }
      fish.velocity.lerp(fish.targetVelocity, phys.turnSpeed);
      fish.velocity.clampLength(fish.speed * 0.85, fish.speed * 1.15);

      pos.add(fish.velocity);

      if (isBottomDweller) {
        pos.y = bottomY;
      } else {
        if (pos.y >= maxY) { pos.y = maxY; fish.velocity.y *= -1; fish.targetVelocity.y = -Math.abs(fish.targetVelocity.y); }
        if (pos.y <= minY) { pos.y = minY; fish.velocity.y *= -1; fish.targetVelocity.y = Math.abs(fish.targetVelocity.y); }
      }

      if (pos.x >= maxX) { pos.x = maxX; fish.velocity.x *= -1; fish.targetVelocity.x = -Math.abs(fish.targetVelocity.x); }
      if (pos.x <= minX) { pos.x = minX; fish.velocity.x *= -1; fish.targetVelocity.x = Math.abs(fish.targetVelocity.x); }
      if (pos.z >= maxZ) { pos.z = maxZ; fish.velocity.z *= -1; fish.targetVelocity.z = -Math.abs(fish.targetVelocity.z); }
      if (pos.z <= minZ) { pos.z = minZ; fish.velocity.z *= -1; fish.targetVelocity.z = Math.abs(fish.targetVelocity.z); }

      let lookTarget: THREE.Vector3;
      if (isBottomDweller) {
        lookTarget = pos.clone().add(new THREE.Vector3(fish.velocity.x, 0, fish.velocity.z));
      } else {
        lookTarget = pos.clone().add(fish.velocity);
      }
      fish.group.lookAt(lookTarget);
    }
  }
}